import json, sys

def text_of(content):
    if isinstance(content, str):
        return content
    out = []
    if isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                continue
            t = c.get('type')
            if t == 'text':
                out.append(c.get('text', ''))
            elif t == 'tool_use':
                inp = json.dumps(c.get('input', {}))[:300]
                out.append(f"[TOOL_USE {c.get('name')}] {inp}")
            elif t == 'tool_result':
                cont = c.get('content')
                if isinstance(cont, list):
                    cont = ' '.join(x.get('text','') for x in cont if isinstance(x, dict))
                s = str(cont)[:300]
                out.append(f"[TOOL_RESULT] {s}")
    return ' '.join(out)

path = sys.argv[1]
with open(path) as f:
    for i, line in enumerate(f):
        obj = json.loads(line)
        t = obj.get('type')
        ts = obj.get('timestamp', '')
        if t in ('assistant', 'user'):
            msg = obj.get('message', {})
            role = msg.get('role', t)
            content = msg.get('content', '')
            txt = text_of(content)
            txt = txt.replace('\n', ' ')[:500]
            print(f"{i} {ts} {role}: {txt}")
        elif t == 'attachment':
            pass
        else:
            pass

